      rules[key] = {
        mode: ["general", "pause", "duck"].includes(rule.mode) ? rule.mode : "general",
        targetVolumePercent: Number.isFinite(target) ? Math.min(100, Math.max(0, Math.round(target))) : null,
        targetVolumeSource
