            if (!active) return;
            if (observer) { observer.disconnect(); observer = null; }
            for (const anchor of tracked) {
                const orig = originals.get(anchor);
                // v1.0.2 (WO-01 round 3, 3-b F5 — round-2 deferred item
                // (d) adjudicated): the isConnected guard is GONE — an
                // anchor modified while enabled but DETACHED at toggle-off
                // (inside the 150 ms flush-prune window, or before a detach
                // batch flushed) was skipped, then forgotten by the clear()
                // below, and re-attached with target="_blank" forever with
                // the module OFF. Restoration works on detached elements,
                // the anchor objects are alive in the Set until this very
                // loop, and everything is dropped right after — zero
                // retention cost, restore-more-only.
                if (orig) {
                    anchor.target = orig.target;
                    anchor.rel = orig.rel;
                }
            }
            tracked.clear();
            originals = new WeakMap();   /* WeakMap has no .clear() — replace */
            active = false;
        };

        return { enable, disable };
    })();

