        btn.type = 'button'; // [06] never submits an ancestor <form> (default type is "submit")
        btn.className = 'psi-btn';
        btn.textContent = CONFIG.labels.init;
        btn.title = `Ψ extract: ${url.slice(0, 80)}${url.length > 80 ? '...' : ''}`;

        btn.onclick = async (e) => {
            e.preventDefault();
            e.stopPropagation();
