    // ═══[13–16] IG AUTO-EXTRACT MODULE — JS port of ig_extract.py (FINAL REVISION) ═══
    const MP4_RE = /https:\/\/[^\s"'<>\\]+?\.mp4(?:\?[^\s"'<>\\]*)?/g;
