        // ── Entry point: text → vault (Route 1 structural, then Route 2 fallback net) ──
        ingest(text) {
            try {
                if (typeof text !== 'string' || !text) return;
                if (text.indexOf('video_versions') === -1 && text.indexOf('video_dash_manifest') === -1 && text.indexOf('.mp4') === -1) return;
