                const tag = e.kind === 'progressive' ? `progressive type ${e.type} — video+audio`
                    : e.kind === 'dash' ? `dash ${e.label} — video-only`
                    : 'fallback net';
                const row = el('div', 'psi-ig-entry');
                const tagEl = el('span', 'psi-ig-tag');
