                const codeEl = el('span', 'psi-ig-code');
                codeEl.textContent = e.code || '';
                row.appendChild(codeEl);
                const urlEl = el('div', 'psi-ig-url');
                urlEl.textContent = e.url.length > 96 ? `${e.url.slice(0, 96)}...` : e.url;
