        },
        sweep() {
            document.querySelectorAll('video').forEach((el) => {
                if (el.hasAttribute('data-psi-locked')) return;
                const u = resolveMediaUrl(el);
                if (u && this.isIgVideoUrl(u)) hookAsset(el, { allowDirect: true });
