    const NET_MEDIA_RE = /https?:\/\/[^\s"'<>\\]+?\.(?:mp4|webm|m3u8|ts|m4s|mpd|mkv|mov|avi|flv|mp3|m4a|ogg|wav|flac|aac|jpg|jpeg|png|webp|gif|avif|bmp)(?:\?[^\s"'<>\\]*)?/gi;

