    .filter((p) => counts[p])
    .map((p) => (counts[p] === 1 ? `${p === 'q' ? 'the' : 'a'} ${NAME[p]}` : `${words[counts[p]] || counts[p]} ${NAME[p]}s`))
    .join(' and ');
}

const Board = {
  VAL, NAME, sq, fileOf, rankOf, other, grid, attacksFrom, attackers, loosePieces,
