(function () {
    'use strict';
    // --- Helpers ---


    function getGameId() {
        const pathParts = location.pathname.split('/').filter(p => p);
        return pathParts.length > 0 ? pathParts[0] : 'global';
    }

    function getDisplayName(gameId) {
        if (gameId === 'global') return 'all games';

        // Try to get the proper name from the page UI first
        const gameNameEl = document.querySelector('.game-name');
        if (gameNameEl && gameNameEl.textContent.trim()) {
            return gameNameEl.textContent.trim();
        }

        // Fallback to capitalizing the URL slug if DOM element isn't found
        return gameId.split('-').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
    }

    const TAB_SELECTORS = [
        '.single-tab',
        '.anchor-row [role="tab"]',
        '.article-layout > [role="tablist"] > [role="tab"]'
    ];

    function getPageTabs() {
        for (const selector of TAB_SELECTORS) {
            const tabs = document.querySelectorAll(selector);
            if (tabs.length > 0) {
                return Array.from(tabs);
            }
        }
        return [];
    }

    function getTabName(tab) {
        const titleEl = tab.querySelector('p, h2, h3, h4, span');
        if (titleEl && titleEl.textContent.trim()) {
            return titleEl.textContent.replace(/\s+/g, ' ').trim();
        }

        const clone = tab.cloneNode(true);
        clone.querySelectorAll('svg').forEach(el => el.remove());
        return clone.textContent.replace(/\s+/g, ' ').trim();
    }

    function isTabActive(tab) {
        return tab.classList.contains('active') || tab.getAttribute('aria-selected') === 'true';
    }

    // --- Settings UI ---

    function createSettingsUI() {
        const gameId = getGameId();
        const storageKey = `defaultTab_${gameId}`;
        const gameDisplayName = getDisplayName(gameId);

        // limit to sections that actually have tabs to avoid clutter
        const tabs = getPageTabs();
        if (tabs.length === 0) {
            alert("No tabs found on this page to configure.");
            return;
        }

        // Create overlay container
        const overlay = document.createElement('div');
        overlay.style.position = 'fixed';
        overlay.style.top = '0';
        overlay.style.left = '0';
        overlay.style.width = '100%';
        overlay.style.height = '100%';
        overlay.style.backgroundColor = 'rgba(0, 0, 0, 0.8)';
        overlay.style.zIndex = '9999';
        overlay.style.display = 'flex';
        overlay.style.flexDirection = 'column';
        overlay.style.justifyContent = 'center';
        overlay.style.alignItems = 'center';
        overlay.style.color = 'white';
        overlay.style.fontFamily = 'sans-serif';

        // Content container
        const content = document.createElement('div');
        content.style.backgroundColor = '#1a1a1a';
        content.style.padding = '20px';
        content.style.borderRadius = '10px';
        content.style.border = '1px solid #444';
        content.style.maxWidth = '400px';
        content.style.textAlign = 'center';

        const title = document.createElement('h2');
        title.textContent = `Default Tab for ${gameDisplayName}`;
        title.style.marginBottom = '10px';
        content.appendChild(title);

        const currentDefault = GM_getValue(storageKey, '');

        const info = document.createElement('p');
        info.append('Current preference: ');
        const prefStrong = document.createElement('strong');
        prefStrong.textContent = currentDefault || 'None (Default)';
        info.appendChild(prefStrong);
        info.appendChild(document.createElement('br'));
        info.appendChild(document.createElement('br'));
        info.append('Click a tab below to set it as your default for ');
        const gameStrong = document.createElement('strong');
        gameStrong.textContent = gameDisplayName;
        info.appendChild(gameStrong);
        info.append(' pages.');
        info.style.marginBottom = '20px';
        content.appendChild(info);

        const btnContainer = document.createElement('div');
        btnContainer.style.display = 'flex';
        btnContainer.style.flexWrap = 'wrap';
        btnContainer.style.gap = '10px';
        btnContainer.style.justifyContent = 'center';

        // Add "None" option
        const noneBtn = document.createElement('button');
        noneBtn.textContent = 'None (Disable Auto-switch)';
        noneBtn.style.padding = '8px 16px';
        noneBtn.style.cursor = 'pointer';
        noneBtn.style.backgroundColor = currentDefault === '' ? '#66bb6a' : '#333';
        noneBtn.style.color = 'white';
        noneBtn.style.border = 'none';
        noneBtn.style.borderRadius = '5px';
        noneBtn.onclick = () => {
            GM_setValue(storageKey, '');
            alert(`Default tab cleared for ${gameDisplayName}.`);
            document.body.removeChild(overlay);
        };
        btnContainer.appendChild(noneBtn);

        // Add buttons for each found tab
        tabs.forEach(tab => {
            const tabName = getTabName(tab);
            if (tabName) {
                const btn = document.createElement('button');
                btn.textContent = tabName;
                btn.style.padding = '8px 16px';
                btn.style.cursor = 'pointer';
                const isSelected = currentDefault.toLowerCase() === tabName.toLowerCase();
                btn.style.backgroundColor = isSelected ? '#66bb6a' : '#333';
                btn.style.color = 'white';
                btn.style.border = 'none';
                btn.style.borderRadius = '5px';

                btn.onclick = () => {
                    GM_setValue(storageKey, tabName); // Store original case for display, but compare loosely
                    alert(`Default tab for ${gameDisplayName} set to: "${tabName}"`);
                    document.body.removeChild(overlay);
                    // Reset switch state so it applies immediately if possible
                    handleNavigation();
                };
                btnContainer.appendChild(btn);
            }
        });

        content.appendChild(btnContainer);

        const closeBtn = document.createElement('button');
        closeBtn.textContent = 'Cancel';
        closeBtn.style.marginTop = '20px';
        closeBtn.style.padding = '8px 16px';
        closeBtn.style.cursor = 'pointer';
        closeBtn.style.backgroundColor = '#d32f2f';
        closeBtn.style.color = 'white';
        closeBtn.style.border = 'none';
        closeBtn.style.borderRadius = '5px';
        closeBtn.onclick = () => document.body.removeChild(overlay);
        content.appendChild(closeBtn);

        overlay.appendChild(content);
        document.body.appendChild(overlay);
    }

    // --- Register Menu Command ---
    GM_registerMenuCommand("Change Default Tab", createSettingsUI);


    // --- Core Logic ---

    // --- History API Hooks & Navigation Handling ---

    let lastUrlWithoutHash = location.pathname + location.search;

    function handleUrlChange() {
        const currentUrlWithoutHash = location.pathname + location.search;
        if (currentUrlWithoutHash !== lastUrlWithoutHash) {
            lastUrlWithoutHash = currentUrlWithoutHash;
            handleNavigation();
        }
    }

    function hookHistoryApi() {
        // Handle popstate (back/forward button)
        window.addEventListener('popstate', handleUrlChange);

        // Patch pushState
        const originalPushState = history.pushState;
        history.pushState = function (...args) {
            originalPushState.apply(this, args);
            handleUrlChange();
        };

        // Patch replaceState
        const originalReplaceState = history.replaceState;
        history.replaceState = function (...args) {
            originalReplaceState.apply(this, args);
            handleUrlChange();
        };
    }

    let pollInterval = null;
    let attempts = 0;
    const MAX_ATTEMPTS = 300; // 300 * 100ms = 30 seconds
    const CHECK_INTERVAL = 100;

    let stabilityCount = 0;
    const REQUIRED_STABILITY = 5; // 5 * 100ms = 500ms stable before we stop

    function handleNavigation() {
        // Clear any existing interval
        if (pollInterval) {
            clearInterval(pollInterval);
        }

        attempts = 0;
        stabilityCount = 0; // Reset stability

        // Start polling
        pollInterval = setInterval(trySwitchTab, CHECK_INTERVAL);

        // Try immediately
        trySwitchTab();
    }

    function trySwitchTab() {
        // Timeout
        if (attempts >= MAX_ATTEMPTS) {
            clearInterval(pollInterval);
            pollInterval = null;
            return;
        }

        attempts++;

        const gameId = getGameId();
        const targetTabName = GM_getValue(`defaultTab_${gameId}`, '');
        const tabs = getPageTabs();

        // If no preference, we can just stop if we see tabs (and they are likely loaded)
        if (!targetTabName) {
            if (tabs.length > 0) {
                clearInterval(pollInterval);
                pollInterval = null;
            }
            return;
        }

        if (tabs.length === 0) return;

        for (const tab of tabs) {
            const tabName = getTabName(tab);
            if (tabName) {
                const tabText = tabName.toLowerCase();

                // Check match
                if (tabText === targetTabName.toLowerCase()) {
                    if (isTabActive(tab)) {
                        // It IS active.
                        stabilityCount++;
                        if (stabilityCount >= REQUIRED_STABILITY) {
                            console.log(`Always that tab on Prydwen: Tab "${tabName}" stable for ${REQUIRED_STABILITY * CHECK_INTERVAL / 1000}s. Stopping checks.`);
                            clearInterval(pollInterval);
                            pollInterval = null;
                        }
                    } else {
                        // It is NOT active. Click it!
                        console.log(`Always that tab on Prydwen: Switching to "${tabName}"...`);
                        tab.click();
                        // Reset stability because we just had to fix it
                        stabilityCount = 0;
                    }
                    // We found our guy, no need to check other tabs
                    return;
                }
            }
        }

        // If we found tabs but NOT our target tab (maybe naming mismatch or dynamic load?),
        // we just keep polling until timeout or until it appears.
    }

    // Initialize
    hookHistoryApi();

    // Check initially on script load
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', handleNavigation);
    } else {
        handleNavigation();
    }

})();

