        let done = 0;

        async function worker() {
            while (cursor < pending.length) {
                const url = pending[cursor++];
                const real = await resolveLucasdLink(url);
                if (real) cache[url] = real;
                resolved.set(url, real);
                done++;
                if (onProgress) onProgress(done, pending.length);
            }
        }

        await Promise.all(Array.from({ length: Math.min(CONCURRENCY, pending.length) }, () => worker()));
        saveLucasdCache(cache);
        return resolved;
    }

    function scanPage() {
        const selectors = [
            'img[class*=bbImage]', 'video source', 'iframe[class*=saint-iframe]',
            'iframe', 'section[class*=message-attachments] a', 'a',
            'span[data-s9e-mediaembed-iframe]'
        ].join(', ');

        const rawLinks = new Set();

        document.querySelectorAll(selectors).forEach(link => {
            let href = link.href || link.src;
            if (!href) return;

            // EAFP Decode
            if (href.includes('goto/link-confirmation?url=')) {
                try {
                    const urlObj = new URL(href);
                    const encodedUrl = urlObj.searchParams.get('url');
                    const decoded = decodeBase64Url(encodedUrl);
                    if (decoded) href = decoded;
                } catch { console.debug('FLX interceptor: unbound'); /* Ignore malformed */ }
            }
            if (href.startsWith('http')) {
                // === THIS IS THE LUCASD FIX (v2 — real-URL aggregation) ===
                // candidshiny video links (/lucasd-LXWn) bypass the exclusion filter
                // — the auto-added self-hostname term would drop them all — and are
                // resolved to their real URLs (https://viderea.cloud/e/...) at
                // EXECUTE time instead of being string-rewritten (the /e/ token is
                // not derivable from the /lucasd- path; the link must be followed).
                if (LUCASD_VIDEO_REGEX.test(href)) {
                    rawLinks.add(href);
                    return;
                }
                // On candidshiny itself, direct viderea/vidara links are targets,
                // not noise — keep them out of the forum-oriented exclusion.
                if (ON_CANDIDSHINY && REAL_HOST_REGEX.test(href)) {
                    rawLinks.add(href);
                    return;
                }
                // O(1) exclusion regex evaluation
                if (EXCLUDE_REGEX.test(href)) return;

                // DOM closeness evaluation
                const isSiteTerm = CONFIG.siteTerms.some(term => link.closest(term));
                if (!isSiteTerm || href.includes('attachment')) {
                    rawLinks.add(href);
                }
            }
        });

        return Array.from(rawLinks);
    }

    function initLinkXtractor() {
        const container = document.createElement('div');
        container.id = 'psi-container';

        const toggleBtn = document.createElement('button');
        toggleBtn.id = 'psi-toggle-btn';
        toggleBtn.title = 'Initialize Extraction Protocol';
        /* v3.2.3 (suite v1.4.3 TT class fix): the glyph is built through
         * createElementNS — innerHTML is a TrustedHTML sink under
         * require-trusted-types-for 'script' (same class as the
         * v1.4.2 glass-kernel repair). Geometry 1:1 with the template. */
        const SVG_NS = 'http://www.w3.org/2000/svg';
        const svgEl = (tag, attrs) => {
            const el = document.createElementNS(SVG_NS, tag);
            for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, v);
            return el;
        };
        const glyphSvg = svgEl('svg', {
            viewBox: '0 0 128 128', xmlns: SVG_NS, fill: 'none',
            stroke: CONFIG.accentColor, 'stroke-width': '3',
            'stroke-linecap': 'round', 'stroke-linejoin': 'round',
        });
        glyphSvg.appendChild(svgEl('path', { class: 'glyph-ring-1', d: 'M 64,12 A 52,52 0 1 1 63.9,12 Z', 'stroke-dasharray': '21.78 21.78', 'stroke-width': '2' }));
        glyphSvg.appendChild(svgEl('path', { class: 'glyph-ring-2', d: 'M 64,20 A 44,44 0 1 1 63.9,20 Z', 'stroke-dasharray': '10 10', 'stroke-width': '1.5' }));
        glyphSvg.appendChild(svgEl('path', { class: 'glyph-hex', d: 'M64 30 L91.3 47 L91.3 81 L64 98 L36.7 81 L36.7 47 Z' }));
        const glyphPsi = svgEl('text', {
            x: '64', y: '70', 'text-anchor': 'middle', 'dominant-baseline': 'middle',
            fill: CONFIG.accentColor, stroke: 'none', 'font-size': '48', 'font-weight': '700',
        });
        glyphPsi.style.fontFamily = "'Cinzel Decorative', serif";
        glyphPsi.textContent = 'Ψ';
        glyphSvg.appendChild(glyphPsi);
        toggleBtn.appendChild(glyphSvg);

        const panel = document.createElement('div');
        panel.id = 'psi-panel';

        function createUIElement(type, id, name, value, checked, labelText) {
            const wrapper = document.createElement('div');
            wrapper.style.display = 'flex'; wrapper.style.alignItems = 'center';
            const input = document.createElement('input');
            input.type = type; input.id = id; input.checked = checked;
            if (name) input.name = name;
            if (value) input.value = value;
            const label = document.createElement('label');
            label.htmlFor = id; label.textContent = labelText; label.style.marginLeft = '5px';
            wrapper.appendChild(input); wrapper.appendChild(label);
            return { wrapper, input };
        }

        // GUI Rows
        const row1 = document.createElement('div'); row1.className = 'psi-row';
        const rDownload = createUIElement('radio', 'opt-dl', 'extract-action', 'download', true, 'Download');
        const rCopy = createUIElement('radio', 'opt-cp', 'extract-action', 'copy', false, 'Copy');
        row1.append(rDownload.wrapper, rCopy.wrapper);

        const row2 = document.createElement('div'); row2.className = 'psi-row';
        const cCurrent = createUIElement('checkbox', 'opt-cur', null, null, false, 'Current Page Only');
        const cSort = createUIElement('checkbox', 'opt-sort', null, null, true, 'Sort Links');
        row2.append(cCurrent.wrapper, cSort.wrapper);

        const row3 = document.createElement('div'); row3.className = 'psi-row';
        row3.id = 'row-separator'; row3.style.display = 'none';
        const sepLabel = document.createElement('span'); sepLabel.textContent = 'Separator: ';
        const sepSelect = document.createElement('select');
        /* v3.2.3: option elements, not an HTML string (TT sink). The
         * newline option keeps the literal two-char "\\n" attribute value
         * the template produced — L578's sepSelect.value check expects it. */
        for (const [val, label] of [['\\n', 'New Line'], [' ', 'Space']]) {
            const opt = document.createElement('option');
            opt.value = val;
            opt.textContent = label;
            sepSelect.appendChild(opt);
        }
        row3.append(sepLabel, sepSelect);

        const row4 = document.createElement('div'); row4.className = 'psi-row';
        const execBtn = document.createElement('button');
        execBtn.className = 'psi-btn'; execBtn.textContent = 'EXECUTE EXTRACTION';
        row4.appendChild(execBtn);

        panel.append(row1, row2, row3, row4);
        container.append(toggleBtn, panel);
        document.body.appendChild(container);

        const toastContainer = document.createElement('div');
        toastContainer.id = 'psi-toast-container';
        document.body.appendChild(toastContainer);

        function showToast(msg, duration = 3000) {
            const toast = document.createElement('div');
            toast.className = 'psi-toast'; toast.textContent = `>> ${msg}`;
            toastContainer.appendChild(toast);
            setTimeout(() => {
                toast.style.opacity = '0'; toast.style.transform = 'translateX(100%)';
                setTimeout(() => toast.remove(), 300);
            }, duration);
        }

        if (typeof GM_registerMenuCommand !== 'undefined') {
            GM_registerMenuCommand('Clear Lucasd URL Cache', () => {
                localStorage.removeItem('psi_lucasd_cache');
                showToast('Lucasd resolution cache cleared.');
            });
        }

        // GUI Listeners
        toggleBtn.addEventListener('click', () => panel.classList.toggle('visible'));
        [rDownload.input, rCopy.input].forEach(input => {
            input.addEventListener('change', () => row3.style.display = rCopy.input.checked ? 'flex' : 'none');
        });

        // v3.2.5 (r18 R18-F15): the thread identity, factored — both the
        // execBtn aggregation and the buffer saves derive it from ONE
        // helper (the auto-save previously had no thread concept at all).
        function currentThreadName() {
            const pathSegments = window.location.pathname.split('#')[0].split('/');
            const threadsIdx = pathSegments.indexOf('threads');
            if (threadsIdx !== -1 && pathSegments[threadsIdx + 1]) {
                return pathSegments[threadsIdx + 1];
            }
            if (ON_CANDIDSHINY && /^lucasd/i.test(pathSegments[1] || '')) {
                return 'lucasd';
            }
            return 'extracted_links';
        }

        execBtn.addEventListener('click', async () => {
            if (execBtn.disabled) return;

            const threadName = currentThreadName();
            const pageURL = window.location.href.split('#')[0];

            // Real-time scan and save
            const currentLinks = scanPage();
            saveLinksToBuffer(pageURL, currentLinks, threadName);

            let finalLinksSet = new Set();
            let aggregatedPages = 0;

            if (!cCurrent.input.checked) {
                try {
                    const savedLinks = JSON.parse(localStorage.getItem('psi_link_buffer') || '{}');
                    /* v3.2.5 (r18 R18-F15): explicit thread identity first
                     * (new-format entries), URL-substring for legacy array
                     * entries — and never the 'extracted_links' default as
                     * an aggregation key (non-thread pages share no
                     * identity; each keeps its own current-page set). */
                    const threadKeys = Object.keys(savedLinks).filter(key => {
                        const entry = savedLinks[key];
                        if (entry && typeof entry === 'object' && !Array.isArray(entry)) {
                            return entry.thread === threadName && threadName !== 'extracted_links';
                        }
                        return key.includes(threadName) && threadName !== 'extracted_links';
                    });
                    threadKeys.forEach(key => {
                        const entry = savedLinks[key];
                        const links = Array.isArray(entry) ? entry : (entry && entry.links) || [];
                        links.forEach(link => finalLinksSet.add(link));
                    });
                    aggregatedPages = threadKeys.length;
                } catch {
                    showToast('Error reading buffer. Falling back to current page.', 4000);
                }
            }
            /* v3.2.5 (r18 R18-F15): the current page's links are ALWAYS in
             * the final set. The default aggregation previously matched
             * saved URL keys by thread-name substring, and on any
             * non-thread page (forum index, search, start.me) the default
             * threadName 'extracted_links' matched NOTHING: currentLinks
             * were saved but never read back and the extraction reported
             * 'No links found.' on a page full of assets. */
            currentLinks.forEach(link => finalLinksSet.add(link));
            showToast(`Aggregated ${aggregatedPages} saved page(s) + current page.`);

            let finalLinks = Array.from(finalLinksSet);

            // === THIS IS THE LUCASD FIX (v2 — resolve to real URLs) ===
            // candidshiny video links collected above (current page + buffered
            // pages of the same thread) are followed over the network and replaced
            // by their real URLs. Unresolved links keep their original form so no
            // data is silently lost; the toast reports how many failed.
            const lucasdLinks = finalLinks.filter(link => LUCASD_VIDEO_REGEX.test(link));
            if (lucasdLinks.length > 0) {
                const originalLabel = execBtn.textContent;
                execBtn.disabled = true;
                execBtn.textContent = 'RESOLVING...';

                const progressToast = document.createElement('div');
                progressToast.className = 'psi-toast';
                progressToast.textContent = `>> Resolving real URLs: 0/${lucasdLinks.length}`;
                toastContainer.appendChild(progressToast);

                try {
                    const resolvedMap = await resolveAllLucasdLinks(lucasdLinks, (done, total) => {
                        progressToast.textContent = `>> Resolving real URLs: ${done}/${total}`;
                    });

                    const reals = [];
                    const unresolved = [];
                    lucasdLinks.forEach(link => {
                        const real = resolvedMap.get(link);
                        if (real) reals.push(real); else unresolved.push(link);
                    });

                    finalLinks = finalLinks
                        .filter(link => !LUCASD_VIDEO_REGEX.test(link))
                        .concat(reals, unresolved);

                    if (unresolved.length > 0) {
                        showToast(`${unresolved.length} lucasd links unresolved — originals kept.`, 5000);
                    }
                } catch (err) {
                    console.error('[Ψ-4NDR0666] Lucasd resolution error:', err);
                    showToast('Lucasd resolution error — originals kept.', 5000);
                } finally {
                    execBtn.disabled = false;
                    execBtn.textContent = originalLabel;
                    setTimeout(() => {
                        progressToast.style.opacity = '0';
                        progressToast.style.transform = 'translateX(100%)';
                        setTimeout(() => progressToast.remove(), 300);
                    }, 1200);
                }
            }

            finalLinks = Array.from(new Set(finalLinks));
            if (cSort.input.checked) finalLinks.sort();

            if (finalLinks.length === 0) {
                showToast('No links found.', 4000);
                return;
            }

            if (rCopy.input.checked) {
                const sep = sepSelect.value === '\\n' ? '\n' : ' ';
                const payload = finalLinks.join(sep);

                if (typeof GM_setClipboard !== 'undefined') {
                    GM_setClipboard(payload);
                    showToast(`Copied ${finalLinks.length} links.`);
                } else if (navigator.clipboard?.writeText) {
                    navigator.clipboard.writeText(payload)
                        .then(() => showToast(`Copied ${finalLinks.length} links.`))
                        .catch(() => showToast('Clipboard Error'));
                }
            } else {
                const blob = new Blob([finalLinks.join('\n')], { type: 'text/plain' });
                const tempLink = document.createElement('a');
                tempLink.href = URL.createObjectURL(blob);
                tempLink.download = `${threadName}.txt`;
                document.body.appendChild(tempLink);
                tempLink.click();
                document.body.removeChild(tempLink);
                URL.revokeObjectURL(tempLink.href);
                showToast(`Downloaded ${finalLinks.length} links.`);
            }
        });

        // Silent Buffer on Load
        const initialLinks = scanPage();
        saveLinksToBuffer(window.location.href.split('#')[0], initialLinks, currentThreadName());
        console.log(`[Ψ-4NDR0666] Background index complete. Buffered ${initialLinks.length} entities.`);
    }

    // =========================================================================
    // MODULE 2: REPLY VIEWER (Promisified & Hardened)
    // =========================================================================

    /** Async wrapper for GM_xmlhttpRequest using the manager's native
     *  timeout — actually aborts the underlying connection (the previous
     *  AbortController shim only rejected the promise late; the request
     *  itself kept running — and a hung request never settled at all). */
    function fetchAnswersAsync(url) {
        return new Promise((resolve, reject) => {
            GM_xmlhttpRequest({
                method: "GET",
                url: url,
                timeout: 12000,
                onerror: (err) => reject(err),
                ontimeout: () => reject(new Error('Request timed out')),
                onabort: () => reject(new Error('Request aborted')),
                onload: (res) => {
                    if (res.status >= 200 && res.status < 300) {
                        resolve(res.responseText);
                    } else {
                        reject(new Error(`HTTP ${res.status}`));
                    }
                }
            });
        });
    }

    function injectReplyButtons() {
        const fullDomain = window.location.hostname;
        const mainDomain = fullDomain.split('.').slice(-2).join('.'); // Extracts simpcity.su from www.simpcity.su

        const posts = document.querySelectorAll(".message.message--post .message-inner");

        posts.forEach(postElement => {
            const mainContainer = postElement.querySelector('.message-main.js-quickEditTarget') || postElement;
            if (!mainContainer || mainContainer.querySelector('.sc-replies-button')) return;

            const btn = document.createElement('button');
            btn.textContent = "View Replies";
            btn.className = "sc-replies-button";
            mainContainer.appendChild(btn);

            btn.addEventListener('click', async (e) => {
                e.preventDefault();
                let repliesContainer = postElement.querySelector('.sc-replies-container');

                if (repliesContainer) {
                    const isHidden = repliesContainer.style.display === 'none';
                    repliesContainer.style.display = isHidden ? 'block' : 'none';
                    btn.textContent = isHidden ? "Hide Replies" : "View Replies";
                    return;
                }

                // Create container
                repliesContainer = document.createElement('div');
                repliesContainer.className = 'sc-replies-container';
                const hunting = document.createElement('strong');
                hunting.style.color = CONFIG.yellowColor;
                hunting.textContent = 'Hunting replies...';
                repliesContainer.replaceChildren(hunting);
                mainContainer.appendChild(repliesContainer);
                btn.textContent = "Hide Replies";

                // EAFP ID Extraction
                try {
                    const messageContent = postElement.closest('.message[data-content]');
                    const postId = messageContent?.getAttribute('data-content')?.replace('post-', '');
                    const headerLink = postElement.querySelector('.message-attribution-main a[href*="/threads/"]');
                    const threadIdMatch = headerLink?.getAttribute("href")?.match(/\.([0-9]+)\/post-/);
                    const threadId = threadIdMatch ? threadIdMatch[1] : null;

                    if (!postId || !threadId) throw new Error("ID resolution failed.");

                    const searchURL = `https://${mainDomain}/search/1/?q=post-${postId}&t=post&c[thread]=${threadId}&o=date`;

                    const htmlText = await fetchAnswersAsync(searchURL);
                    const doc = TTparse.html(htmlText);
                    const answerBlocks = doc.querySelectorAll("li.block-row.block-row--separated.js-inlineModContainer[data-author]");

                    if (!answerBlocks || answerBlocks.length === 0) {
                        const none = document.createElement('strong');
                        none.textContent = 'No replies found.';
                        repliesContainer.replaceChildren(none);
                        return;
                    }

                    repliesContainer.replaceChildren();
                    const table = document.createElement("table");
                    table.className = "sc-replies-table";
                    const thead = document.createElement("thead");
                    const headRow = document.createElement("tr");
                    for (const h of ["Post #", "Date", "Reply Snippet"]) {
                        const th = document.createElement("th");
                        th.textContent = h;
                        headRow.appendChild(th);
                    }
                    thead.appendChild(headRow);
                    table.appendChild(thead);
                    const tbody = document.createElement("tbody");

                    answerBlocks.forEach((block) => {
                        const postLink = block.querySelector('.contentRow-main a[href*="/post-"]');
                        const postTime = block.querySelector('time.u-dt');
                        const contentSnippet = block.querySelector('.contentRow-snippet');

                        if (postLink?.href && postTime && contentSnippet) {
                            const row = document.createElement("tr");
                            const postIdMatch = postLink.href.match(/\/post-(\d+)/);
                            const postIdText = postIdMatch ? `#${postIdMatch[1]}` : 'Link';

                            /* v3.2.3: row cells via createElement. The
                             * v3.2.2 template interpolated remote snippet
                             * text raw into HTML — a post containing markup
                             * would have been parsed as markup (latent
                             * injection hazard); textContent renders it as
                             * visible text, which is what the table means. */
                            const tdNum = document.createElement('td');
                            tdNum.style.textAlign = 'center';
                            const postA = document.createElement('a');
                            postA.href = postLink.href;
                            postA.target = '_blank';
                            postA.textContent = postIdText;
                            tdNum.appendChild(postA);
                            const tdDate = document.createElement('td');
                            tdDate.style.textAlign = 'center';
                            tdDate.style.whiteSpace = 'nowrap';
                            tdDate.textContent = postTime.textContent.trim();
                            const tdSnippet = document.createElement('td');
                            tdSnippet.textContent = contentSnippet.textContent.trim();
                            row.append(tdNum, tdDate, tdSnippet);
                            tbody.appendChild(row);
                        }
                    });
                    table.appendChild(tbody);
                    repliesContainer.appendChild(table);

                } catch (err) {
                    console.error('[Ψ-4NDR0666] Reply fetch error:', err);
                    const errStrong = document.createElement('strong');
                    errStrong.style.color = CONFIG.redColor;
                    errStrong.textContent = `Fetch Error: ${err.message}`;
                    repliesContainer.replaceChildren(errStrong);
                }
            });
        });
    }

    // =========================================================================
    // MODULE 3: DEFENSIVE ORCHESTRATION (Dynamic Injection)
    // =========================================================================
    let _debounceTimer = null;

    function bootstrap() {
        if (!document.body) {
            setTimeout(bootstrap, 50);
            return;
        }

        // Init isolated core modules
        initLinkXtractor();

        // Initial synchronous DOM pass
        setTimeout(injectReplyButtons, 800);

        // Bounded structural observer for lazy-loaded posts/pages
        const observer = new MutationObserver((mutations) => {
            const structural = mutations.some(m => m.addedNodes.length > 0);
            if (!structural) return;

            clearTimeout(_debounceTimer);
            _debounceTimer = setTimeout(injectReplyButtons, 400);
        });

        observer.observe(document.body, { childList: true, subtree: true });

        // Garbage collection
        window.addEventListener('beforeunload', () => observer.disconnect(), { once: true });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', bootstrap);
    } else {
        bootstrap();
    }

})();

