                    }
                } catch (error) {
                    logError('mountDomSurfaces', error);
                }
            };

            if (document.body) {
                mountDomSurfaces();
            } else {
                document.addEventListener('DOMContentLoaded', mountDomSurfaces, { once: true });
            }

            settingsChanged(() => {
                displaySearchLinks();
                displayDriveLinks();
                syncSettingsConsole();
            });
        } catch (error) {
            logError('initialize', error);
        }
    };

    initialize();
})();

