            this.cloneRegistry.set(url, { blob: clone, mime: clone.type || '', size: clone.size || 0, ts: Date.now(), minted: !!mintedByUs });
            this.totalCloneBytes += clone.size || 0;
            /* v6.1.1 (7b F02/F03): eviction honors BOTH bounds — count AND the
             * aggregate byte budget — and revokes the object URLs WE minted
             * (canvas captures, re-mints): an un-revoked self-minted URL pins
             * its blob's bytes in the URL store for the document's lifetime,
             * so the 120-entry FIFO bounded bookkeeping only, not memory.
             * Page-owned keys are never revoked (that would break the page).
             * The newest entry always survives (size>1 guard) — one giant
             * capture beats evicting everything to chase the budget. */
            while ((this.cloneRegistry.size > this.maxClones || (this.totalCloneBytes > this.maxCloneBytes && this.cloneRegistry.size > 1))) {
                const oldest = this.cloneRegistry.keys().next().value;
                if (oldest === undefined) break;
                const entry = this.cloneRegistry.get(oldest);
                this.cloneRegistry.delete(oldest);
                this.totalCloneBytes -= (entry && entry.size) || 0;
                if (this.totalCloneBytes < 0) this.totalCloneBytes = 0;
                if (entry && entry.minted && this.nativeRevokeObjectURL) {
                    try { this.nativeRevokeObjectURL.call(URL, oldest); } catch (revokeError) {
                        Logger.debug('Self-minted clone URL revoke rejected.', revokeError);
                    }
                }
                if (this.totalCloneBytes > this.maxCloneBytes) {
                    Logger.warn(`Clone registry byte budget exceeded (${(this.totalCloneBytes / 1048576).toFixed(1)} MiB retained); dropped a ${((entry && entry.size) || 0)}-byte clone aged ${Math.max(0, Date.now() - ((entry && entry.ts) || Date.now()))} ms.`);
                }
            }
        }

        hasClone(url) {
            return typeof url === 'string' && this.cloneRegistry.has(url);
        }

        getClone(url) {
            const entry = typeof url === 'string' ? this.cloneRegistry.get(url) : null;
            return entry ? entry.blob : null;
        }

        /* Re-mint a FRESH object URL for a (possibly dead) one, from the
         * clone — the vault-validity fallback. Uses the saved native so our
         * own wrap never re-enters. */
        remintCloneUrl(url) {
            const entry = typeof url === 'string' ? this.cloneRegistry.get(url) : null;
            if (!entry || !this.nativeCreateObjectURL) return null;
            try {
                const fresh = this.nativeCreateObjectURL.call(URL, entry.blob);
                if (typeof fresh === 'string') {
                    /* v6.1.1 (7b F02): the re-minted URL is OURS — register it
                     * minted so eviction revokes it (an untracked re-mint
                     * leaked its URL entry for the document lifetime). */
                    this.registerClone(fresh, entry.blob, true);
                    /* v6.1.2 (8b F06): the OLD entry retires with the re-mint —
                     * the registry held the same blob TWICE (a transient 2x
                     * byte-budget charge; registerClone's eviction may already
                     * have removed it, so the delete() return decides the
                     * subtraction), and the old URL is the re-mint's dead
                     * premise — its minted-ness decides the revoke. */
                    if (this.cloneRegistry.delete(url)) {
                        this.totalCloneBytes -= entry.size || 0;
                        if (this.totalCloneBytes < 0) this.totalCloneBytes = 0;
                    }
                    if (entry.minted && this.nativeRevokeObjectURL) {
                        try { this.nativeRevokeObjectURL.call(URL, url); } catch (revokeError) {
                            Logger.debug('Retired re-mint source URL revoke rejected.', revokeError);
                        }
                    }
                    return fresh;
                }
                return null;
            } catch (mintError) {
                Logger.debug('Vault clone re-mint rejected by the URL runtime.', mintError);
                return null;
            }
        }

        /* v6.2.0: swap a registry entry's blob for the REPAIRED bytes — budget
         * accounting adjusted so eviction stays honest; the PAGE's own URL
         * still references the original blob (page semantics were never
         * ours to touch) — the vault's SAVE/re-mint serve the clean bytes. */
        repairRegistryEntry(url, repaired) {
            try {
                const entry = typeof url === 'string' ? this.cloneRegistry.get(url) : null;
                if (!entry || !this.isBlobLike(repaired)) return;
                this.totalCloneBytes -= entry.size || 0;
                if (this.totalCloneBytes < 0) this.totalCloneBytes = 0;
                entry.blob = repaired;
                entry.size = repaired.size || 0;
                entry.mime = repaired.type || entry.mime;
                this.totalCloneBytes += entry.size;
                Logger.info(`Vault clone repaired in place (${url}) — the SAVE path now serves clean ${entry.mime} bytes.`);
            } catch (repairError) {
                Logger.debug('Vault entry repair bookkeeping rejected.', repairError);
            }
        }

        /* ── hook family 1: URL.createObjectURL clone-at-create ─────────────── */

        installObjectUrlWrap() {
            try {
                const nativeCreate = URL.createObjectURL;
                if (typeof nativeCreate !== 'function') return;
                this.nativeCreateObjectURL = nativeCreate;
                if (typeof URL.revokeObjectURL === 'function') this.nativeRevokeObjectURL = URL.revokeObjectURL;
                const self = this;
                URL.createObjectURL = function (blobOrMediaSource) {
                    const url = nativeCreate.apply(this, arguments);
                    try {
                        if (self.isBlobLike(blobOrMediaSource) && blobOrMediaSource.size > 0) {
                            const rawClone = blobOrMediaSource.slice(0);
                            self.registerClone(url, rawClone);
                            /* v6.2.0 (round 12): the vault copy is repaired
                             * ASYNCHRONOUSLY — the page's URL and bytes are
                             * untouched (page semantics first); when the site
                             * handed out a double-encoded blob the registry
                             * entry swaps to the clean bytes (the operator's
                             * standing blob-decryption field report — the
                             * samples decode byte-for-byte back to valid
                             * JPEGs). */
                            BlobSanitizer.repairBlob(rawClone)
                                .then((repaired) => { if (repaired) self.repairRegistryEntry(url, repaired); })
                                .catch((repairError) => {
                                    /* G11: the raw clone stays on any repair
                                     * rejection — best-effort, never silent. */
                                    Logger.debug('Vault clone repair rejected; the raw clone stays.', repairError);
                                });
                        }
                    } catch (cloneError) {
                        Logger.debug('Object-URL clone registration rejected; the page URL is unaffected.', cloneError);
                    }
                    return url;
                };
            } catch (installError) {
                Logger.warn('createObjectURL interception was not installed (page sealed the API?).', installError);
            }
        }

        /* ── hook family 2: canvas buffer-commit capture ───────────────────── */

        installCanvasHooks() {
            try {
                if (typeof HTMLCanvasElement === 'undefined') return;
                const proto = HTMLCanvasElement.prototype;
                if (typeof proto.toDataURL !== 'function' || typeof proto.toBlob !== 'function') return;
                this.nativeToDataURL = proto.toDataURL;
                this.nativeToBlob = proto.toBlob;
                const self = this;
                proto.toDataURL = function () {
                    const result = self.nativeToDataURL.apply(this, arguments);
                    try { self.captureCanvasCommit(this, null, result); } catch (hookError) {
                        Logger.debug('Canvas toDataURL capture rejected; the page result is unaffected.', hookError);
                    }
                    return result;
                };
                proto.toBlob = function (callback) {
                    const canvas = this;
                    const args = Array.prototype.slice.call(arguments);
                    if (typeof callback === 'function') {
                        args[0] = function (blob) {
                            try { self.captureCanvasCommit(canvas, blob, null); } catch (hookError) {
                                Logger.debug('Canvas toBlob capture rejected; the page callback is unaffected.', hookError);
                            }
                            callback(blob);
                        };
                    }
                    return self.nativeToBlob.apply(this, args);
                };
            } catch (installError) {
                Logger.warn('Canvas commit hooks were not installed (prototype sealed?).', installError);
            }
        }

        captureCanvasCommit(canvas, blob, dataUrl) {
            try {
                if (!canvas || typeof canvas.width !== 'number' || typeof canvas.height !== 'number') return;
                if (canvas.width * canvas.height < this.minCanvasPixels) return;
            } catch (shapeError) {
                Logger.debug('Canvas shape probe rejected; commit not captured.', shapeError);
                return;
            }
            if (this.isBlobLike(blob) && blob.size >= this.minCaptureBytes) {
                this.ingestCapturedBlob(blob);
                return;
            }
            if (typeof dataUrl === 'string' && dataUrl.length >= Math.ceil(this.minCaptureBytes * 4 / 3) && dataUrl.startsWith('data:')) {
                /* data: URL → Blob via the page fetch API (data: URLs never
                 * hit the network and need no @connect grant). v6.1.1 (7b
                 * F13): the base64 inflation is accounted — the string form
                 * carried a ~25% lower effective byte floor than toBlob's. */
                fetch(dataUrl)
                    .then(res => {
                        if (!res.ok) throw new Error(`data: conversion returned HTTP ${res.status}`);
                        return res.blob();
                    })
                    .then(converted => {
                        if (converted && converted.size >= this.minCaptureBytes) this.ingestCapturedBlob(converted);
                    })
                    .catch(convError => Logger.debug('Canvas dataURL commit conversion rejected.', convError));
            }
        }

        ingestCapturedBlob(blob) {
            if (!this.isBlobLike(blob) || blob.size < this.minCaptureBytes) return;
            let subtle = null;
            try {
                subtle = window.crypto && window.crypto.subtle && typeof window.crypto.subtle.digest === 'function'
                    ? window.crypto.subtle : null;
            } catch (probeError) {
                Logger.debug('crypto.subtle probe rejected; canvas capture skipped.', probeError);
            }
            if (!subtle) {
                Logger.debug('Canvas capture skipped: crypto.subtle unavailable in this context.');
                return;
            }
            blob.arrayBuffer()
                .then(buffer => subtle.digest('SHA-256', buffer))
                .then(digest => {
                    const hash = Array.from(new Uint8Array(digest)).slice(0, 8)
                        .map(b => b.toString(16).padStart(2, '0')).join('');
                    if (this.canvasHashes.has(hash)) return; // already captured
                    const clone = blob.slice(0);
                    if (!this.nativeCreateObjectURL) return;
                    const url = this.nativeCreateObjectURL.call(URL, clone);
                    if (typeof url !== 'string') return;
                    this.registerClone(url, clone, true);
                    this.dispatchVaultCapture({ src: url, type: 'image' });
                    /* v6.1.1 (7b F08): the hash commits only AFTER the capture
                     * entered the vault — a failed mint/register used to mark
                     * the content captured forever, a permanently lost capture
                     * on re-commit. */
                    this.canvasHashes.add(hash);
                    this.canvasHashOrder.push(hash);
                    while (this.canvasHashOrder.length > this.maxCanvasHashes) {
                        this.canvasHashes.delete(this.canvasHashOrder.shift());
                    }
                    Logger.info(`Canvas commit captured into the vault (sha256 ${hash.slice(0, 8)}, ${blob.size} bytes).`);
                })
                .catch(hashError => Logger.debug('Canvas capture hashing rejected.', hashError));
        }

        /* ── hook family 3: DOM stalker ─────────────────────────────────────── */

        installDomStalker() {
            try {
                if (typeof MutationObserver !== 'function') return;
                /* Arrow callbacks bind `this` to the platform instance — no
                 * realm-shaped `self` alias (the global census deliberately
                 * scans the `self` realm; an alias here reads as pollution). */
                this.stalkObserver = new MutationObserver((mutations) => {
                    for (const mutation of mutations) {
                        /* v6.1.1 (7b F04): attribute-only mutations — a lazy
                         * <img> whose src materializes, a React re-render that
                         * only swaps src, a <source> quality switch — never
                         * delivered addedNodes, so the elements were invisible
                         * to the stalker after the baseline sweep. */
                        if (mutation.type === 'attributes') {
                            if (mutation.target && mutation.target.nodeType === 1) this.queueStalkNode(mutation.target);
                            continue;
                        }
                        if (!mutation.addedNodes || mutation.addedNodes.length === 0) continue;
                        for (const node of mutation.addedNodes) {
                            if (!node || node.nodeType !== 1) continue; // ELEMENT_NODE
                            this.queueStalkNode(node);
                        }
                    }
                    if (this.stalkQueue.size === 0) return;
                    if (this.stalkSweepFloorAt === 0) this.stalkSweepFloorAt = Date.now();
                    if (this.stalkDebounceTimer) clearTimeout(this.stalkDebounceTimer);
                    /* v6.1.1 (7b F10): max-latency cap — every mutation batch
                     * reset the 400 ms trailing debounce, so continuous churn
                     * (agent token streaming) postponed the sweep for the
                     * burst duration; 2 s after the FIRST queued node the
                     * sweep fires regardless. */
                    if (Date.now() - this.stalkSweepFloorAt >= 2000) {
                        this.stalkSweepFloorAt = 0;
                        if (this.stalkDebounceTimer) { clearTimeout(this.stalkDebounceTimer); this.stalkDebounceTimer = null; }
                        this.runStalkSweep();
                        return;
                    }
                    this.stalkDebounceTimer = setTimeout(() => {
                        this.stalkDebounceTimer = null;
                        this.stalkSweepFloorAt = 0;
                        this.runStalkSweep();
                    }, 400);
                });
                this.stalkObserver.observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ['src', 'href'] });
                /* Baseline sweep for nodes already in the DOM when the
                 * platform arms late (readyState already interactive) —
                 * v6.1.1 (7b F01): the sweep must ENQUEUE the existing nodes
                 * first; draining an empty queue was a no-op (first install
                 * mid-session, manager update re-injection, bfcache restore
                 * never stalker-captured anything). */
                const enqueueExistingDom = () => {
                    try {
                        if (typeof document.querySelectorAll === 'function') {
                            for (const el of document.querySelectorAll('a[href], img, video, source')) {
                                this.stalkQueue.add(el);
                            }
                        }
                    } catch (baselineError) {
                        Logger.debug('Baseline DOM enqueue rejected.', baselineError);
                    }
                };
                if (document.readyState !== 'loading') {
                    enqueueExistingDom();
                    this.runStalkSweep();
                } else {
                    window.addEventListener('DOMContentLoaded', () => { enqueueExistingDom(); this.runStalkSweep(); }, { once: true });
                }
            } catch (installError) {
                Logger.warn('DOM stalker was not installed (observer API sealed?).', installError);
            }
        }

        queueStalkNode(node) {
            try {
                const tag = node.tagName;
                if (tag === 'A' || tag === 'IMG' || tag === 'VIDEO' || tag === 'SOURCE') {
                    /* v6.1.2 (8b F14): the sweep floor anchors at ENQUEUE time —
                     * the observer callback anchored it at the first mutation
                     * BATCH, and the debounce path reset it to 0 after every
                     * sweep, so alternating quiet/churn phases granted each
                     * burst a fresh 2 s window; the '2 s after the FIRST queued
                     * node' contract holds from the queue's own birth now. */
                    if (this.stalkQueue.size === 0 && this.stalkSweepFloorAt === 0) this.stalkSweepFloorAt = Date.now();
                    this.stalkQueue.add(node);
                } else if (typeof node.querySelectorAll === 'function') {
                    for (const el of node.querySelectorAll('a[href], img, video, source')) {
                        this.stalkQueue.add(el);
                    }
                }
            } catch (queueError) {
                Logger.debug('Stalk queue admission rejected for one node.', queueError);
            }
        }

        runStalkSweep() {
            if (this.stalkQueue.size === 0) return;
            const pending = Array.from(this.stalkQueue);
            this.stalkQueue.clear();
            for (const el of pending) {
                try {
                    if (!el.isConnected) continue;
                    this.captureFromElement(el);
                } catch (elementError) {
                    Logger.debug('Stalk sweep rejected one element capture.', elementError);
                }
            }
        }

        captureFromElement(el) {
            const tag = el.tagName;
            let src = '';
            let type = 'image';
            if (tag === 'VIDEO') {
                src = String(el.currentSrc || el.src || '').trim();
                if (!src) {
                    const source = el.querySelector('source');
                    src = source ? String(source.src || source.getAttribute('src') || '').trim() : '';
                }
                if (!src) src = String(el.getAttribute('data-src') || '').trim();
                type = 'video';
            } else if (tag === 'SOURCE') {
                src = String(el.src || el.getAttribute('src') || '').trim();
                const parent = el.parentElement;
                type = parent && parent.tagName === 'VIDEO' ? 'video' : 'image';
            } else if (tag === 'IMG') {
                src = String(el.currentSrc || el.src || '').trim() || String(el.getAttribute('data-src') || '').trim();
                type = 'image';
            } else if (tag === 'A') {
                src = String(el.href || el.getAttribute('href') || '').trim();
                type = this.videoExtRe.test(src) ? 'video' : 'image';
            }
            if (!src) return;
            if (!this.isVaultWorthy(src, tag)) return;
            this.dispatchVaultCapture({ src, type });
        }

        isVaultWorthy(src, tag) {
            if (src.startsWith('blob:')) return this.hasClone(src); // site-generated media with a live clone
            if (!/^https?:/i.test(src)) return false;               // data: and relatives are UI noise
            if (tag === 'VIDEO' || tag === 'SOURCE') return true;   // every video target is media
            if (this.mediaExtRe.test(src)) return true;             // direct media file URL
            try {
                const parsed = new URL(src, location.href);
                if (this.hailuoHosts.includes(parsed.hostname)) {
                    return /\/(video|image|media|oss|files?)\//i.test(parsed.pathname) || this.mediaExtRe.test(src);
                }
            } catch (urlError) {
                Logger.debug('Vault-worthiness URL parse rejected; target skipped.', urlError);
            }
            return false;
        }

        /* ── stability: page error isolation ────────────────────────────────── */

        installPageErrorIsolation() {
            try {
                /* v6.1.1 (7b F07): observe-only telemetry, debug-gated — the
                 * capture phase sees every failed resource load too, which
                 * doubled the console line count on the site's own documented
                 * noisy upstream whenever devtools Verbose was on; the
                 * rejection reason stringification is guarded (a Symbol reason
                 * used to throw INSIDE the error handler itself). These are
                 * observers, not isolators — nothing is swallowed. */
                window.addEventListener('error', (event) => {
                    if (!Logger.debugEnabled) return;
                    Logger.debug('Page error observed (interception platform remains armed).', event && event.message);
                }, true);
                window.addEventListener('unhandledrejection', (event) => {
                    if (!Logger.debugEnabled) return;
                    let reason = '';
                    try { reason = String(event && event.reason); } catch (stringifyError) { reason = '<unstringifiable>'; }
                    Logger.debug('Unhandled rejection observed (interception platform remains armed).', reason);
                });
            } catch (installError) {
                Logger.warn('Page error isolation listeners were not installed.', installError);
            }
        }

        /* ── sink ───────────────────────────────────────────────────────────── */

        dispatchVaultCapture(assetObj) {
            try {
                if (this.sink && this.sink.uiFactory && this.sink.uiFactory.assetBayStore) {
                    this.sink.uiFactory.captureAssetIntoBay(assetObj);
                }
            } catch (sinkError) {
                Logger.debug('Vault capture dispatch rejected by the bay layer.', sinkError);
            }
        }
    }

