  let mode = 'sf19';
  const LABELS = {
    sf19: 'Stockfish 19 NNUE · on-device',
    sf10: 'Stockfish 10 (fallback) · on-device',
    online: 'Stockfish · chess-api.com (online)',
  };

  const withTimeout = (p, ms, msg) => Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(unavailable(msg)), ms))]);

