      'self.onmessage=function(e){var bytes=e.data;' +
      'self.fetch=function(){return Promise.resolve(new Response(bytes,{headers:{"Content-Type":"application/wasm"}}))};' +
      'self.onmessage=null;__cmcBoot();};\nfunction __cmcBoot(){\n';
