  }

  async function bootSf10() {
    const src = GM_getResourceText('sf10');
    if (!src) throw new Error('fallback engine missing');
    const eng = UciEngine(new Worker(URL.createObjectURL(new Blob([src], { type: 'text/javascript' }))));
